.libPaths(c('UCEC_论文执行_v2_20261013/10_软件环境/R-library','UCEC_启动_20261013/11_版本与审查记录/软件环境/R-library',.libPaths()))
suppressPackageStartupMessages({library(Matrix);library(SingleCellExperiment);library(jsonlite)})
base<-'UCEC_论文执行_v2_20261013';sample<-commandArgs(TRUE)[1];dir<-file.path(base,'03_单细胞',sample);if(!file.exists(file.path(dir,'qc_sce.rds')))quit(status=2);if(file.exists(file.path(dir,'annotation_complete.json')))quit(status=0)
sce<-readRDS(file.path(dir,'qc_sce.rds'));plan<-fromJSON(file.path(base,'00_冻结方案/执行方案_v2.json'));m<-assay(sce,'decontXlogcounts');cl<-sce$pre_cluster
panels<-list(Epithelial=c('EPCAM','KRT8','KRT18','KRT19','KRT7','CDH1','MUC1','PAX8'),Myeloid=c('LYZ','LST1','TYROBP','FCER1G','AIF1','CTSS','CSF1R','CD68'),T_cell=c('CD3D','CD3E','TRAC','IL7R'),NK_cell=c('NKG7','GNLY','KLRD1','PRF1'),B_cell=c('CD79A','MS4A1','CD74','CD79B'),Plasma_cell=c('MZB1','JCHAIN','SDC1','XBP1'),Stromal=c('COL1A1','COL1A2','COL3A1','DCN','LUM','COL6A1','COL6A2','PDGFRA'),Endothelial=c('PECAM1','VWF','EMCN','KDR','CLDN5','RAMP2'),Perivascular=c('RGS5','PDGFRB','CSPG4','MCAM','ACTA2','TAGLN','MYH11'))
sc<-sapply(panels,function(gs)colMeans(m[intersect(gs,rownames(m)),,drop=FALSE]));cluster_scores<-sapply(unique(cl),function(k)colMeans(sc[cl==k,,drop=FALSE]));cluster_scores<-t(cluster_scores);rownames(cluster_scores)<-unique(cl)
labels<-character(nrow(cluster_scores));gaps<-numeric(nrow(cluster_scores));evidence<-list()
specific<-list(Epithelial=c('EPCAM','KRT8','KRT18','KRT19','PAX8','CDH1'),Myeloid=c('LST1','TYROBP','FCER1G','CSF1R','AIF1'),T_cell=c('CD3D','CD3E','TRAC'),NK_cell=c('NKG7','GNLY','KLRD1','PRF1'),B_cell=c('CD79A','MS4A1','CD79B'),Plasma_cell=c('MZB1','JCHAIN'),Stromal=c('COL1A1','COL1A2','DCN','LUM'),Endothelial=c('PECAM1','VWF','CLDN5'),Perivascular=c('RGS5','PDGFRB','CSPG4','MCAM','ACTA2','TAGLN','MYH11'))
for(i in seq_len(nrow(cluster_scores))){
 k<-rownames(cluster_scores)[i];supported<-setNames(integer(length(panels)),names(panels));eligible<-setNames(logical(length(panels)),names(panels));summaries<-list()
 for(n in names(panels)){
  gs<-intersect(panels[[n]],rownames(m));det<-rowMeans(counts(sce)[gs,cl==k,drop=FALSE]>0);meanexpr<-rowMeans(m[gs,cl==k,drop=FALSE]);supported[n]<-sum(det>=.1 & meanexpr>=ifelse(sce$dataset[1]=='GSE173682',.2,.1));core<-intersect(specific[[n]],gs);need<-if(n %in% c('B_cell','Plasma_cell','Endothelial'))1 else 2;eligible[n]<-supported[n]>=2 && sum(det[core]>=.1 & meanexpr[core]>=ifelse(sce$dataset[1]=='GSE173682',.2,.1))>=need;summaries[[n]]<-paste(sprintf('%s:%.2f',gs,det),collapse=';')
 }
 v<-sort(setNames(as.numeric(cluster_scores[i,eligible]),colnames(cluster_scores)[eligible]),decreasing=TRUE)
 if(!length(v)){best<-names(which.max(cluster_scores[i,]));gaps[i]<-NA;labels[i]<-'Ambiguous';bestscore<-max(cluster_scores[i,])} else {best<-names(v)[1];gaps[i]<-if(length(v)>1)v[1]-v[2] else v[1];bestscore<-v[1];labels[i]<-if(v[1]>=ifelse(sce$dataset[1]=='GSE173682',.3,.15) && gaps[i]>=ifelse(sce$dataset[1]=='GSE173682',.15,.075))best else 'Ambiguous'}
 evidence[[i]]<-data.frame(cluster=k,top_panel=best,assigned=labels[i],best_score=bestscore,margin=gaps[i],supported_markers=supported[best],cells=sum(cl==k),marker_summary=summaries[[best]])
}
ann<-setNames(labels,rownames(cluster_scores));sce$fine_label<-unname(ann[cl]);sce$coarse_label<-ifelse(sce$fine_label %in% c('T_cell','NK_cell','B_cell','Plasma_cell'),'Lymphoid',sce$fine_label);sce$annotation_margin<-setNames(gaps,rownames(cluster_scores))[cl]
write.csv(data.frame(cluster=rownames(cluster_scores),cluster_scores,check.names=FALSE),file.path(dir,'聚类标记评分.csv'),row.names=FALSE);write.csv(do.call(rbind,evidence),file.path(dir,'注释证据.csv'),row.names=FALSE)
cell<-read.csv(file.path(dir,'细胞坐标与质控.csv'));cell$coarse_label<-sce$coarse_label[match(cell$barcode,colnames(sce))];cell$fine_label<-sce$fine_label[match(cell$barcode,colnames(sce))];cell$annotation_margin<-sce$annotation_margin[match(cell$barcode,colnames(sce))]
# Per-lineage pseudobulk retains raw and corrected counts, including uncertain cells in a separate compartment.
labels2<-unique(sce$coarse_label);raw<-sapply(labels2,function(k)rowSums(counts(sce)[,sce$coarse_label==k,drop=FALSE]));corrected<-sapply(labels2,function(k)rowSums(assay(sce,'decontXcounts')[,sce$coarse_label==k,drop=FALSE]));rownames(raw)<-rownames(corrected)<-rownames(sce);write.csv(raw,gzfile(file.path(dir,'raw_pseudobulk.csv.gz')));write.csv(corrected,gzfile(file.path(dir,'corrected_pseudobulk.csv.gz')))
write.csv(data.frame(sample=sample,lineage=names(table(sce$coarse_label)),cells=as.integer(table(sce$coarse_label))),file.path(dir,'患者谱系细胞数.csv'),row.names=FALSE)
# Separate expression and detection to expose dropout/ambient dependence.
programs<-c(plan$generic_programs,list(legacy_up=plan$legacy_signed_panel$up,legacy_down=plan$legacy_signed_panel$down,response_up=plan$formal_source_response_panel$up,response_down=plan$formal_source_response_panel$down))
detection<-list();for(k in labels2){ids<-sce$coarse_label==k;for(n in names(programs)){gs<-intersect(programs[[n]],rownames(sce));detection[[length(detection)+1]]<-data.frame(sample=sample,lineage=k,program=n,defined_genes=length(programs[[n]]),assayed_genes=length(gs),median_gene_detected_fraction=median(rowMeans(counts(sce)[gs,ids,drop=FALSE]>0)),cells=sum(ids))}}
write.csv(do.call(rbind,detection),file.path(dir,'程序检出覆盖.csv'),row.names=FALSE);write.csv(cell,file.path(dir,'细胞注释与坐标.csv'),row.names=FALSE)
# A compact gene-by-cell sparse corrected matrix supports expression-state and uncertainty analysis without loading full SCE in Python.
saveRDS(list(counts=assay(sce,'decontXcounts'),raw=counts(sce),metadata=cell,genes=rownames(sce)),file.path(dir,'annotated_sparse.rds'),compress=FALSE)
# Export selected programs and independent markers for per-cell state analysis; retain raw counts here for quality sensitivity.
gs<-unique(unlist(programs));gs<-intersect(gs,rownames(sce));write.csv(as.matrix(assay(sce,'decontXlogcounts')[gs,,drop=FALSE]),gzfile(file.path(dir,'预设基因逐细胞表达.csv.gz')));write.csv(as.matrix(logcounts(sce)[gs,,drop=FALSE]),gzfile(file.path(dir,'预设基因逐细胞原表达.csv.gz')))
write_json(list(sample=sample,coarse_counts=as.list(table(sce$coarse_label)),annotation='Canonical marker consensus with lineage-specific gates; ubiquitous XBP1/CD74 do not alone define plasma/B cells; conservative assay-specific thresholds before response-score inspection; ambiguous retained; epithelial not automatically malignant',source_assay='decontXlogcounts; raw sensitivity retained'),file.path(dir,'annotation_complete.json'),pretty=TRUE,auto_unbox=TRUE);cat('ANNOTATED',sample,'\n')
